CREATE FUNCTION public.lms_reissue_code(p_id uuid,p_hash text,p_expires timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.redeem_codes; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; SELECT * INTO c FROM public.redeem_codes WHERE id=p_id FOR UPDATE; IF NOT FOUND OR c.redeemed_at IS NOT NULL THEN RAISE EXCEPTION 'Used codes cannot be reissued'; END IF; IF length(p_hash)<>64 OR p_expires<=now() THEN RAISE EXCEPTION 'A valid future expiry is required'; END IF; UPDATE public.redeem_codes SET code_hash=p_hash,expires_at=p_expires,revoked_at=NULL WHERE id=c.id; INSERT INTO public.audit_events(actor_id,action,entity_id) VALUES(auth.uid(),'code.reissued',c.id::text); END $$; REVOKE ALL ON FUNCTION public.lms_reissue_code(uuid,text,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lms_reissue_code(uuid,text,timestamptz) TO authenticated;
CREATE TRIGGER device_session_update_validation BEFORE UPDATE ON public.registered_devices FOR EACH ROW WHEN (NEW.revoked_at IS NULL) EXECUTE FUNCTION public.lms_validate_device_session();
CREATE OR REPLACE FUNCTION public.lms_save_progress(p_lesson uuid,p_position integer,p_completed boolean,p_hash text,p_session text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.lessons; BEGIN IF p_session IS DISTINCT FROM auth.jwt()->>'session_id' OR auth.jwt()->>'session_id' IS NULL THEN RAISE EXCEPTION 'Device session does not match your sign-in'; END IF; IF NOT EXISTS(SELECT 1 FROM public.registered_devices WHERE user_id=auth.uid() AND token_hash=p_hash AND session_id=p_session AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Active device required'; END IF; SELECT * INTO l FROM public.lessons WHERE id=p_lesson AND status='published'; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.modules m JOIN public.enrollments e ON e.course_id=m.course_id WHERE m.id=l.module_id AND e.user_id=auth.uid() AND e.revoked_at IS NULL AND e.expires_at>now()) THEN RAISE EXCEPTION 'Active course access required'; END IF; IF p_position<0 OR p_position>l.duration_seconds THEN RAISE EXCEPTION 'Invalid playback position'; END IF; INSERT INTO public.lesson_progress(user_id,lesson_id,position_seconds,completed) VALUES(auth.uid(),p_lesson,p_position,p_completed AND p_position>=l.duration_seconds*0.9 AND l.duration_seconds>0) ON CONFLICT(user_id,lesson_id) DO UPDATE SET position_seconds=p_position,completed=lesson_progress.completed OR EXCLUDED.completed,updated_at=now(); END $$;